import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    Shape,
    ShapeGeometry,
    PlaneGeometry,
    CircleGeometry,
    Color,
  } = ctx.THREE;

  const root = new Group();
  root.name = config.id ?? 'collection-badge';

  const timelines = [];
  const primitiveCleanups = [];
  const ownedResources = [];
  let disposed = false;

  const makeCapsule = (width, height, radius) => {
    const halfWidth = width * 0.5;
    const halfHeight = height * 0.5;
    const r = Math.min(radius, halfHeight, halfWidth);

    const shape = new Shape();
    shape.moveTo(-halfWidth + r, -halfHeight);
    shape.lineTo(halfWidth - r, -halfHeight);
    shape.quadraticCurveTo(halfWidth, -halfHeight, halfWidth, -halfHeight + r);
    shape.lineTo(halfWidth, halfHeight - r);
    shape.quadraticCurveTo(halfWidth, halfHeight, halfWidth - r, halfHeight);
    shape.lineTo(-halfWidth + r, halfHeight);
    shape.quadraticCurveTo(-halfWidth, halfHeight, -halfWidth, halfHeight - r);
    shape.lineTo(-halfWidth, -halfHeight + r);
    shape.quadraticCurveTo(-halfWidth, -halfHeight, -halfWidth + r, -halfHeight);

    return new ShapeGeometry(shape);
  };

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y),
  );
  backdropMaterial.depthWrite = false;
  ownedResources.push(backdropMaterial);

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
  backdrop.name = 'designed-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  ownedResources.push(backdrop.geometry);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });
  ownedResources.push(shadowMaterial);

  const shadow = new Mesh(new CircleGeometry(1.55, 48), shadowMaterial);
  shadow.name = 'contact-shadow';
  shadow.scale.set(1.65, 0.28, 1);
  shadow.position.set(0, -0.47, -0.02);
  root.add(shadow);
  ownedResources.push(shadow.geometry);

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
  });
  ownedResources.push(edgeMaterial);

  const edge = new Mesh(makeCapsule(2.7, 0.82, 0.41), edgeMaterial);
  edge.name = 'accent-edge';
  edge.position.z = 0.08;
  root.add(edge);
  ownedResources.push(edge.geometry);

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: new Color('#16161d'),
  });
  ownedResources.push(surfaceMaterial);

  const surface = new Mesh(makeCapsule(2.62, 0.74, 0.37), surfaceMaterial);
  surface.name = 'ceramic-badge-surface';
  surface.position.z = 0.12;
  root.add(surface);
  ownedResources.push(surface.geometry);

  const paperMaterial = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
    transparent: true,
    opacity: 0.12,
  });
  ownedResources.push(paperMaterial);

  const highlight = new Mesh(makeCapsule(2.48, 0.035, 0.017), paperMaterial);
  highlight.name = 'paper-highlight';
  highlight.position.set(0, 0.29, 0.14);
  root.add(highlight);
  ownedResources.push(highlight.geometry);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) return;
      surfaceMaterial.map = texture;
      surfaceMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const card = new Group();
  card.name = 'interactive-badge';
  card.position.z = 0.22;
  root.add(card);
  card.add(edge, surface, highlight);

  const baseY = card.position.y;
  const baseScale = card.scale.clone();

  const killMotion = () => {
    while (timelines.length) timelines.pop().kill();
  };

  const hoverIn = () => {
    killMotion();
    const timeline = gsap.timeline();
    timeline.to(card.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    });
    timeline.to(card.rotation, {
      x: -0.025,
      y: 0.035,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    timelines.push(timeline);
  };

  const hoverOut = () => {
    killMotion();
    const timeline = gsap.timeline();
    timeline.to(card.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power3.out',
    });
    timeline.to(card.rotation, {
      x: 0,
      y: 0,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
    timelines.push(timeline);
  };

  const press = () => {
    killMotion();
    const timeline = gsap.timeline();
    timeline.to(card.scale, {
      x: baseScale.x * 0.97,
      y: baseScale.y * 0.97,
      z: baseScale.z * 0.97,
      duration: 0.12,
      ease: 'power2.out',
    });
    timeline.to(card.scale, {
      x: baseScale.x,
      y: baseScale.y,
      z: baseScale.z,
      duration: 0.35,
      ease: 'back.out(2.2)',
    });
    timelines.push(timeline);
    ctx.emit('hub-collection.select', {
      nodeId: config.id ?? 'hub-collection-badge',
      parent: 'hub-collection',
    });
  };

  const focus = () => {
    gsap.to(edgeMaterial.color, {
      r: 1,
      g: 0.08,
      b: 0.14,
      duration: 0.2,
      ease: 'power2.out',
    });
    edge.scale.set(1.012, 1.012, 1.012);
  };

  const blur = () => {
    gsap.to(edgeMaterial.color, {
      r: 1,
      g: 0.165,
      b: 0.22,
      duration: 0.25,
      ease: 'power2.out',
    });
    edge.scale.set(1, 1, 1);
  };

  root.userData.handlers = {
    hover: (active) => (active ? hoverIn() : hoverOut()),
    click: press,
    focus,
    blur,
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const factory = ctx.primitives?.[primitive.name];
    if (typeof factory === 'function') {
      const result = factory(root, primitive.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    }
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    killMotion();

    for (const cleanup of primitiveCleanups) cleanup();

    for (const resource of ownedResources) {
      if (resource?.dispose) resource.dispose();
    }

    root.traverse((object) => {
      if (object.userData) delete object.userData.handlers;
    });
  };

  return root;
}
